-- Privacy-first event memory, scoring decisions and operational Radar.
ALTER TABLE users ADD COLUMN personalization_consent INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS nervous_events (id TEXT PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,actor_type TEXT NOT NULL CHECK(actor_type IN ('anonymous','user','admin','system')),actor_hash TEXT,session_hash TEXT,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,content_id TEXT REFERENCES content_items(id) ON DELETE SET NULL,campaign_id TEXT REFERENCES business_campaigns(id) ON DELETE SET NULL,page_path TEXT NOT NULL DEFAULT '',locale TEXT NOT NULL DEFAULT 'fr',device_class TEXT NOT NULL DEFAULT 'unknown',source TEXT NOT NULL DEFAULT 'web',consent_tier TEXT NOT NULL DEFAULT 'contextual' CHECK(consent_tier IN ('contextual','personalized')),metadata_json TEXT NOT NULL DEFAULT '{}',filtered INTEGER NOT NULL DEFAULT 0,filter_reason TEXT,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_nervous_events_type_time ON nervous_events(event_type,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_nervous_events_content ON nervous_events(content_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_nervous_events_user ON nervous_events(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS user_interest_profiles (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,topic TEXT NOT NULL,raw_score REAL NOT NULL DEFAULT 0,normalized_score REAL NOT NULL DEFAULT 0,confidence REAL NOT NULL DEFAULT 0,last_signal_at TEXT NOT NULL,updated_at TEXT NOT NULL,algorithm_version TEXT NOT NULL DEFAULT 'editorial-v1',PRIMARY KEY(user_id,topic));
CREATE TABLE IF NOT EXISTS content_features (content_id TEXT PRIMARY KEY REFERENCES content_items(id) ON DELETE CASCADE,category TEXT NOT NULL,topics_json TEXT NOT NULL DEFAULT '[]',entities_json TEXT NOT NULL DEFAULT '[]',technologies_json TEXT NOT NULL DEFAULT '[]',countries_json TEXT NOT NULL DEFAULT '[]',format TEXT NOT NULL,editorial_importance REAL NOT NULL DEFAULT .5,quality_score REAL NOT NULL DEFAULT .5,trust_score REAL NOT NULL DEFAULT .5,freshness_score REAL NOT NULL DEFAULT .5,feature_version TEXT NOT NULL DEFAULT 'editorial-v1',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_relations (source_content_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,target_content_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,relation_type TEXT NOT NULL,weight REAL NOT NULL DEFAULT 0,evidence_json TEXT NOT NULL DEFAULT '{}',computed_at TEXT NOT NULL,PRIMARY KEY(source_content_id,target_content_id,relation_type));
CREATE TABLE IF NOT EXISTS algorithm_versions (engine TEXT PRIMARY KEY,version TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS algorithm_config (config_key TEXT PRIMARY KEY,numeric_value REAL,text_value TEXT,minimum REAL,maximum REAL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS algorithm_decisions (id TEXT PRIMARY KEY,decision_key TEXT NOT NULL UNIQUE,engine TEXT NOT NULL,version TEXT NOT NULL,decision_type TEXT NOT NULL,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,content_id TEXT REFERENCES content_items(id) ON DELETE SET NULL,campaign_id TEXT REFERENCES business_campaigns(id) ON DELETE SET NULL,score REAL,reason_json TEXT NOT NULL DEFAULT '{}',result_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_algorithm_decisions_time ON algorithm_decisions(engine,created_at DESC);
CREATE TABLE IF NOT EXISTS radar_signals (id TEXT PRIMARY KEY,signal_key TEXT NOT NULL UNIQUE,signal_type TEXT NOT NULL,subject_key TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('info','warning','critical')),score REAL NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')),detected_at TEXT NOT NULL,resolved_at TEXT);
CREATE INDEX IF NOT EXISTS idx_radar_open ON radar_signals(status,severity,detected_at DESC);
CREATE TABLE IF NOT EXISTS nervous_daily_metrics (metric_date TEXT NOT NULL,dimension_type TEXT NOT NULL,dimension_key TEXT NOT NULL,value REAL NOT NULL DEFAULT 0,provisional INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(metric_date,dimension_type,dimension_key));
CREATE TABLE IF NOT EXISTS nervous_system_runs (id TEXT PRIMARY KEY,run_type TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,detail_json TEXT NOT NULL DEFAULT '{}',error_text TEXT);
INSERT OR IGNORE INTO algorithm_versions(engine,version,enabled,updated_at) VALUES ('editorial','editorial-v1',1,CURRENT_TIMESTAMP),('sponsored','sponsored-v1',1,CURRENT_TIMESTAMP),('radar','radar-v1',1,CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO algorithm_config(config_key,numeric_value,minimum,maximum,updated_at) VALUES ('feature_enabled',1,0,1,CURRENT_TIMESTAMP),('editorial_interest_weight',.34,0,.6,CURRENT_TIMESTAMP),('editorial_freshness_weight',.24,0,.6,CURRENT_TIMESTAMP),('editorial_importance_weight',.20,0,.6,CURRENT_TIMESTAMP),('editorial_diversity_weight',.22,0,.6,CURRENT_TIMESTAMP),('sponsor_session_cap',2,0,4,CURRENT_TIMESTAMP),('sponsor_daily_cap',3,0,8,CURRENT_TIMESTAMP),('radar_trend_threshold',8,3,100,CURRENT_TIMESTAMP),('raw_event_retention_days',90,30,180,CURRENT_TIMESTAMP);
